UndefinedFunction.code:
install_drupal($class_loader, $parameters, function ($install_state) use ($progress_bar) {
      static $started = FALSE;
      if (!$started) {
        $started = TRUE;
        // We've already done 1.
        $progress_bar->setFormat("%current%/%max% [%bar%]\n%message%\n");
        $progress_bar->setMessage((string) $this->t('Installing @drupal', ['@drupal' => drupal_install_profile_distribution_name()]));
        $tasks = install_tasks($install_state);
        $progress_bar->start(count($tasks) + 1);
      }
      $tasks_to_perform = install_tasks_to_perform($install_state);
      $task = current($tasks_to_perform);
      if (isset($task['display_name'])) {
        $progress_bar->setMessage((string) $task['display_name']);
      }
      $progress_bar->advance();
    })

InvalidReturnType.code:
return $string_translation->translate(
      'Unable to install %extension due to unmet dependencies: %config_names',
      [
        '%config_names' => static::formatConfigObjectList($this->configObjects),
        '%extension' => $extension,
      ]
    );

return array_filter(array_keys($this->linkTemplates()), function ($link_relation_type) {
      // It's not guaranteed that every link relation type also has a
      // corresponding route. For some, additional modules or configuration may
      // be necessary. The interface demands that we only return supported URI
      // relationships.
      try {
        $this->toUrl($link_relation_type)->toString(TRUE)->getGeneratedUrl();
      }
      catch (RouteNotFoundException) {
        return FALSE;
      }
      catch (MissingMandatoryParametersException) {
        return FALSE;
      }
      return TRUE;
    });

return array_keys(array_filter($this->fieldNames, function ($table_fields) use ($field_name) {
      return in_array($field_name, $table_fields, TRUE);
    }));

return array_unique([
      ...array_keys($language_manager::getStandardLanguageList()),
      // We can't use LanguageInterface::STATE_ALL because it will exclude the
      // site default language in certain situations.
      // @see \Drupal\Core\Language\LanguageManager::filterLanguages()
      ...array_keys($language_manager->getLanguages(LanguageInterface::STATE_LOCKED | LanguageInterface::STATE_CONFIGURABLE | LanguageInterface::STATE_SITE_DEFAULT)),
      // Include special language codes used internally.
      LanguageInterface::LANGCODE_NOT_APPLICABLE,
      LanguageInterface::LANGCODE_SITE_DEFAULT,
      LanguageInterface::LANGCODE_DEFAULT,
      LanguageInterface::LANGCODE_SYSTEM,
      LanguageInterface::LANGCODE_NOT_SPECIFIED,
    ]);

return $this->t('<a href=":login">Log in</a> or <a href=":register">register</a> to post comments', [
          ':login' => Url::fromRoute('user.login', [], ['query' => $destination])->toString(),
          ':register' => Url::fromRoute('user.register', [], ['query' => $destination])->toString(),
        ]);

return $this->t('<a href=":login">Log in</a> to post comments', [
          ':login' => Url::fromRoute('user.login', [], ['query' => $destination])->toString(),
        ]);

